import pandas as pd
def clean(df):
    df = df.drop_duplicates()
    df['species'] = df['species'].str.strip().str.title()
    return df
def answer(df):
    adelie = df[df['species'] == 'Adelie']
    grouped = adelie.groupby('island')['bill_length_mm'].mean().reset_index()
    result = {}
    for _, row in grouped.iterrows():
        result[row['island']] = row['bill_length_mm']
    result['all'] = adelie['bill_length_mm'].mean()
    return result
